def find_rectangles(grid):
    """Find all colored rectangles in the grid."""
    from collections import defaultdict
    color_cells = defaultdict(list)
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            color = grid[r][c]
            if color > 0:
                color_cells[color].append((r, c))

    rects = {}
    for color, cells in color_cells.items():
        minr = min(r for r,c in cells)
        maxr = max(r for r,c in cells)
        minc = min(c for r,c in cells)
        maxc = max(c for r,c in cells)

        border_cells = []
        interior_cells = []
        for r in range(minr, maxr + 1):
            for c in range(minc, maxc + 1):
                if r == minr or r == maxr or c == minc or c == maxc:
                    border_cells.append((r, c))
                else:
                    interior_cells.append((r, c))

        all_border_same = all(grid[r][c] == color for r,c in border_cells)
        all_interior_zero = all(grid[r][c] == 0 for r,c in interior_cells)

        is_hollow = all_border_same and all_interior_zero

        rects[color] = {
            'minr': minr, 'maxr': maxr, 'minc': minc, 'maxc': maxc,
            'h': maxr - minr + 1, 'w': maxc - minc + 1,
            'is_square': (maxr - minr + 1) == (maxc - minc + 1),
            'is_hollow': is_hollow,
        }

    return rects

def apply_transform(layout):
    """Apply transformation: square->delete, rectangle->X-fill"""
    from copy import deepcopy
    result = deepcopy(layout)
    rects = find_rectangles(layout)

    for color, info in rects.items():
        minr, maxr = info['minr'], info['maxr']
        minc, maxc = info['minc'], info['maxc']
        h, w = info['h'], info['w']

        if not info['is_hollow']:
            continue
        elif info['is_square']:
            for r in range(minr, maxr + 1):
                for c in range(minc, maxc + 1):
                    result[r][c] = 0
        else:
            for r in range(minr + 1, maxr):
                for c in range(minc + 1, maxc):
                    ir = r - minr - 1
                    ic = c - minc - 1
                    if ir == ic or ir == (w - 2) - ic:
                        result[r][c] = color

    return result

